import json

order = {"row_id":"O0000-09","order_id":"ORD-0000-09","batch":"partner","currency":"USD","amount_cents":3249}
payments = [{"row_id":"P0000-11","event_id":"PE-0000-09-a","payment_id":"PAY-0000-09-a","order_id":"ORD-0000-09","currency":"USD","amount_cents":3126,"status":"succeeded"}]
refunds = [{"row_id":"R0000-06","event_id":"RE-0000-09","refund_id":"REF-0000-09","payment_id":"PAY-0000-09-a","order_id":"ORD-0000-09","currency":"USD","amount_cents":100,"status":"pending"}]
expected = order["amount_cents"]

# dedup by event_id
def dedup(rows):
    seen=set(); out=[]
    for r in rows:
        if r["event_id"] in seen: continue
        seen.add(r["event_id"]); out.append(r)
    return out

prows = dedup(payments)
rrows = dedup(refunds)
duplicate = len(prows)<len(payments) or len(rrows)<len(refunds)

succ_pay = {p["payment_id"] for p in prows if p["status"]=="succeeded"}
gross = sum(p["amount_cents"] for p in prows if p["status"]=="succeeded")
refund = sum(r["amount_cents"] for r in rrows if r["status"]=="succeeded" and r["payment_id"] in succ_pay)

payment_ids = sorted({p["payment_id"] for p in prows if p["status"]=="succeeded"})
refund_ids = sorted({r["refund_id"] for r in rrows if r["status"]=="succeeded" and r["payment_id"] in succ_pay})
source_rows = sorted([order["row_id"]]+[p["row_id"] for p in payments]+[r["row_id"] for r in refunds])

an=set()
if gross<expected: an.add("underpaid")
if gross>expected: an.add("overpaid")
if len(payment_ids)>1: an.add("multiple_successful_payments")
if refund>gross: an.add("over_refunded")
if any(p["status"]=="failed" for p in payments): an.add("payment_failed")
if any(p["status"]=="pending" for p in payments): an.add("payment_pending")
if any(r["status"]=="failed" for r in refunds): an.add("refund_failed")
if any(r["status"]=="pending" for r in refunds): an.add("refund_pending")
if duplicate: an.add("duplicate_delivery")

if gross==0: state="unpaid"
elif refund>gross: state="over_refunded"
elif refund==gross: state="fully_refunded"
elif refund>0: state="partially_refunded"
elif gross<expected: state="underpaid"
elif gross>expected: state="overpaid"
else: state="paid"

res={"order_id":order["order_id"],"batch":order["batch"],"currency":"USD",
 "expected_cents":expected,"gross_paid_cents":gross,"refund_cents":refund,
 "net_cents":gross-refund,"state":state,"anomalies":sorted(an),
 "payment_ids":payment_ids,"refund_ids":refund_ids,"source_rows":source_rows}
print(json.dumps(res,indent=2))
PY"}

